Object.assign(window.FN_SYNTAX=window.FN_SYNTAX||{},{
"REGEXREPLACE":["=REGEXREPLACE(文字列, パターン, 置換文字列, [出現回数], [大文字小文字])","文字列: 対象の文字列｜パターン: 正規表現｜置換文字列: 置き換え後の文字列｜出現回数: Excelのみ。何番目の一致を置換するか。0=すべて(既定)、負の数は末尾から｜大文字小文字: Excelのみ。0=区別する(既定)、1=区別しない｜※スプレッドシートは最初の3引数のみ"],
"REGEXTEST":["=REGEXTEST(文字列, パターン, [大文字小文字])","文字列: 判定する文字列｜パターン: 正規表現｜大文字小文字: 0=区別する(既定)、1=区別しない"],
"REPLACE":["=REPLACE(文字列, 開始位置, 文字数, 置換文字列)","文字列: 元の文字列｜開始位置: 置換を始める位置(先頭が1)｜文字数: 置き換える文字数｜置換文字列: 差し替える文字列"],
"REPLACEB":["=REPLACEB(文字列, 開始位置, バイト数, 置換文字列)","文字列: 元の文字列｜開始位置: 置換を始めるバイト位置(先頭が1)｜バイト数: 置き換えるバイト数(全角は2バイト)｜置換文字列: 差し替える文字列"],
"REPT":["=REPT(文字列, 繰り返し回数)","文字列: 繰り返す文字列｜繰り返し回数: 繰り返す回数(0以上)"],
"RIGHT":["=RIGHT(文字列, [文字数])","文字列: 元の文字列｜文字数: 右端から取り出す文字数(省略時 1)"],
"RIGHTB":["=RIGHTB(文字列, [バイト数])","文字列: 元の文字列｜バイト数: 右端から取り出すバイト数(省略時 1、全角は2バイト)"],
"SEARCH":["=SEARCH(検索文字列, 対象, [開始位置])","検索文字列: 探す文字列(Excelは ? と * のワイルドカード可)｜対象: 検索される文字列｜開始位置: 検索を始める位置(省略時 1)"],
"SEARCHB":["=SEARCHB(検索文字列, 対象, [開始位置])","検索文字列: 探す文字列｜対象: 検索される文字列｜開始位置: 検索を始めるバイト位置(省略時 1)。結果もバイト位置で返る"],
"SPLIT":["=SPLIT(文字列, 区切り文字, [各文字で分割], [空の文字列を削除])","文字列: 分割する文字列｜区切り文字: 区切りに使う文字(複数可)｜各文字で分割: TRUE=区切り文字の1文字ごとに分割(既定)、FALSE=区切り文字全体で分割｜空の文字列を削除: TRUE=空の要素を除く(既定)、FALSE=残す"],
"SUBSTITUTE":["=SUBSTITUTE(文字列, 検索文字列, 置換文字列, [置換対象])","文字列: 元の文字列｜検索文字列: 置き換えたい文字列｜置換文字列: 置き換え後の文字列｜置換対象: 何番目の一致を置換するか(省略時 すべて)"],
"T":["=T(値)","値: 調べる値。文字列ならそのまま、それ以外は空文字列を返す"],
"TEXT":["=TEXT(値, 表示形式)","値: 変換する数値・日付｜表示形式: 書式コードを \"\" で囲む(例 \"yyyy/mm/dd\"、\"#,##0\"、\"0.0%\")"],
"TEXTAFTER":["=TEXTAFTER(文字列, 区切り文字, [インスタンス番号], [一致モード], [末尾一致], [見つからない場合])","文字列: 対象の文字列｜区切り文字: この文字より後ろを取り出す｜インスタンス番号: 何番目の区切り文字か(既定 1、負の数は末尾から)｜一致モード: 0=大文字小文字を区別(既定)、1=区別しない｜末尾一致: 0=しない(既定)、1=文字列の末尾を区切り文字とみなす｜見つからない場合: 返す値(省略時 #N/A)"],
"TEXTBEFORE":["=TEXTBEFORE(文字列, 区切り文字, [インスタンス番号], [一致モード], [末尾一致], [見つからない場合])","文字列: 対象の文字列｜区切り文字: この文字より前を取り出す｜インスタンス番号: 何番目の区切り文字か(既定 1、負の数は末尾から)｜一致モード: 0=大文字小文字を区別(既定)、1=区別しない｜末尾一致: 0=しない(既定)、1=文字列の末尾を区切り文字とみなす｜見つからない場合: 返す値(省略時 #N/A)"],
"TEXTJOIN":["=TEXTJOIN(区切り文字, 空のセルは無視, 文字列1, [文字列2], …)","区切り文字: 間に挟む文字列｜空のセルは無視: TRUE=空のセルを飛ばす、FALSE=空のセルも連結｜文字列1: 連結する文字列・範囲｜文字列2: 追加で連結する値(省略可)"],
"TEXTSPLIT":["=TEXTSPLIT(文字列, 列区切り, [行区切り], [空を無視], [一致モード], [埋め込み値])","文字列: 分割する文字列｜列区切り: 列方向に分ける区切り文字｜行区切り: 行方向に分ける区切り文字｜空を無視: TRUE=連続する区切りを無視、FALSE=空のセルを作る(既定)｜一致モード: 0=大文字小文字を区別(既定)、1=区別しない｜埋め込み値: 不足セルを埋める値(省略時 #N/A)"],
"TRANSLATE":["=TRANSLATE(文字列, [元の言語], [翻訳先の言語])","文字列: 翻訳するテキスト｜元の言語: 言語コード(例 \"en\"、\"ja\")。省略時は自動検出｜翻訳先の言語: 言語コード。省略時はシステムの言語"],
"TRIM":["=TRIM(文字列)","文字列: 前後のスペースを削除し、単語間のスペースを1つにする文字列"],
"UNICHAR":["=UNICHAR(数値)","数値: 文字に変換するUnicode番号(10進数)"],
"UNICODE":["=UNICODE(文字列)","文字列: 先頭文字のUnicode番号を調べる文字列"],
"UPPER":["=UPPER(文字列)","文字列: 大文字に変換する文字列"],
"VALUE":["=VALUE(文字列)","文字列: 数値に変換する文字列(数値・日付・時刻の形式)"],
"VALUETOTEXT":["=VALUETOTEXT(値, [書式])","値: 文字列に変換する値｜書式: 0=簡潔な形式(既定)、1=厳密な形式(文字列を \"\" で囲むなど数式で再利用できる形)"],
"YEN":["=YEN(数値, [桁数])","数値: 円記号付きの文字列にする数値｜桁数: 小数点以下の桁数(省略時 0、負の数は整数部を四捨五入)"],
"DATE":["=DATE(年, 月, 日)","年: 西暦の年｜月: 月(1〜12。範囲外は前後の年に繰り越し)｜日: 日(範囲外は前後の月に繰り越し)"],
"DATEDIF":["=DATEDIF(開始日, 終了日, 単位)","開始日: 期間の最初の日付｜終了日: 期間の最後の日付｜単位: \"Y\"=満年数、\"M\"=満月数、\"D\"=日数、\"MD\"=月・年を無視した日数、\"YM\"=年を無視した月数、\"YD\"=年を無視した日数"],
"DATEVALUE":["=DATEVALUE(日付文字列)","日付文字列: 日付を表す文字列(例 \"2025/4/1\")"],
"DAY":["=DAY(日付)","日付: 日(1〜31)を取り出す日付"],
"DAYS":["=DAYS(終了日, 開始日)","終了日: 期間の終わりの日付｜開始日: 期間の始まりの日付(終了日が先の引数)"],
"DAYS360":["=DAYS360(開始日, 終了日, [方式])","開始日: 期間の始まり｜終了日: 期間の終わり｜方式: FALSE=米国(NASD)方式(既定)、TRUE=ヨーロッパ方式"],
"EDATE":["=EDATE(開始日, 月)","開始日: 基準の日付｜月: 加える月数(負の数で前の月)"],
"EOMONTH":["=EOMONTH(開始日, 月)","開始日: 基準の日付｜月: 加える月数(0=当月末、負の数で前の月)"],
"EPOCHTODATE":["=EPOCHTODATE(タイムスタンプ, [単位])","タイムスタンプ: UNIXエポック時間｜単位: 1=秒(既定)、2=ミリ秒、3=マイクロ秒｜※結果はUTCの日時"],
"HOUR":["=HOUR(時刻)","時刻: 時(0〜23)を取り出す時刻・日時"],
"ISOWEEKNUM":["=ISOWEEKNUM(日付)","日付: ISO 8601方式の週番号を調べる日付"],
"MINUTE":["=MINUTE(時刻)","時刻: 分(0〜59)を取り出す時刻・日時"],
"MONTH":["=MONTH(日付)","日付: 月(1〜12)を取り出す日付"],
"NETWORKDAYS":["=NETWORKDAYS(開始日, 終了日, [祭日])","開始日: 期間の始まり｜終了日: 期間の終わり｜祭日: 稼働日から除く日付の範囲(省略可)"],
"NETWORKDAYS.INTL":["=NETWORKDAYS.INTL(開始日, 終了日, [週末], [祭日])","開始日: 期間の始まり｜終了日: 期間の終わり｜週末: 1=土日(既定)、2=日月、3=月火、4=火水、5=水木、6=木金、7=金土、11=日のみ〜17=土のみ、または月曜始まり7桁の文字列(例 \"0000011\"、1が休日)｜祭日: 稼働日から除く日付の範囲"],
"NOW":["=NOW()","引数なし(再計算のたびに現在の日時に更新される)"],
"SECOND":["=SECOND(時刻)","時刻: 秒(0〜59)を取り出す時刻・日時"],
"TIME":["=TIME(時, 分, 秒)","時: 時(0〜23)｜分: 分(60以上は時に繰り上げ)｜秒: 秒(60以上は分に繰り上げ)"],
"TIMEVALUE":["=TIMEVALUE(時刻文字列)","時刻文字列: 時刻を表す文字列(例 \"18:30\")"],
"TODAY":["=TODAY()","引数なし(再計算のたびに今日の日付に更新される)"],
"WEEKDAY":["=WEEKDAY(日付, [種類])","日付: 曜日を調べる日付｜種類: 1=日曜1〜土曜7(既定)、2=月曜1〜日曜7、3=月曜0〜日曜6。Excelは 11〜17(月曜〜日曜を週の始まり=1とする)も指定可"],
"WEEKNUM":["=WEEKNUM(日付, [週の基準])","日付: 週番号を調べる日付｜週の基準: 1=日曜始まり(既定)、2=月曜始まり、11〜17=月曜〜日曜始まり、21=ISO方式(月曜始まり)"],
"WORKDAY":["=WORKDAY(開始日, 日数, [祭日])","開始日: 起算日｜日数: 進める稼働日数(負の数で過去)｜祭日: 稼働日から除く日付の範囲(省略可)"],
"WORKDAY.INTL":["=WORKDAY.INTL(開始日, 日数, [週末], [祭日])","開始日: 起算日｜日数: 進める稼働日数(負の数で過去)｜週末: 1=土日(既定)、2=日月、3=月火、4=火水、5=水木、6=木金、7=金土、11=日のみ〜17=土のみ、または月曜始まり7桁の文字列(例 \"0000011\"、1が休日)｜祭日: 稼働日から除く日付の範囲"],
"YEAR":["=YEAR(日付)","日付: 年(西暦)を取り出す日付"],
"YEARFRAC":["=YEARFRAC(開始日, 終了日, [基準])","開始日: 期間の始まり｜終了日: 期間の終わり｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"ACCRINT":["=ACCRINT(発行日, 最初の利払日, 受渡日, 利率, 額面, 頻度, [基準], [計算方式])","発行日: 証券の発行日｜最初の利払日: 最初に利息が支払われる日｜受渡日: 証券の受渡日｜利率: 年間クーポン利率｜額面: 証券の額面(Excelは省略時 1,000)｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360｜計算方式: Excelのみ。TRUE=発行日から計算(既定)、FALSE=最初の利払日から計算"],
"ACCRINTM":["=ACCRINTM(発行日, 満期日, 利率, 額面, [基準])","発行日: 証券の発行日｜満期日: 証券の満期日(Excelの引数名は受渡日)｜利率: 年間クーポン利率｜額面: 証券の額面(Excelは省略時 1,000)｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"AMORDEGRC":["=AMORDEGRC(取得価額, 購入日, 開始期, 残存価額, 期, 率, [基準])","取得価額: 資産の取得価額｜購入日: 資産の購入日｜開始期: 最初の会計期の終了日｜残存価額: 耐用年数終了時の価額｜期: 償却費を求める会計期(最初の期が0)｜率: 減価償却率｜基準: 年の日数 0=360日(NASD、既定)、1=実際、3=365日、4=360日(欧州)"],
"AMORLINC":["=AMORLINC(取得価額, 購入日, 開始期, 残存価額, 期, 率, [基準])","取得価額: 資産の取得価額｜購入日: 資産の購入日｜開始期: 最初の会計期の終了日｜残存価額: 耐用年数終了時の価額｜期: 償却費を求める会計期(最初の期が0)｜率: 減価償却率｜基準: 年の日数 0=360日(NASD、既定)、1=実際、3=365日、4=360日(欧州)"],
"COUPDAYBS":["=COUPDAYBS(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"COUPDAYS":["=COUPDAYS(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"COUPDAYSNC":["=COUPDAYSNC(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"COUPNCD":["=COUPNCD(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"COUPNUM":["=COUPNUM(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"COUPPCD":["=COUPPCD(受渡日, 満期日, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"CUMIPMT":["=CUMIPMT(利率, 期間, 現在価値, 開始期, 終了期, 支払期日)","利率: 1期あたりの利率｜期間: 支払回数の合計｜現在価値: 借入額｜開始期: 累計を始める期(最初が1)｜終了期: 累計を終える期｜支払期日: 0=期末払い、1=期首払い(省略不可)"],
"CUMPRINC":["=CUMPRINC(利率, 期間, 現在価値, 開始期, 終了期, 支払期日)","利率: 1期あたりの利率｜期間: 支払回数の合計｜現在価値: 借入額｜開始期: 累計を始める期(最初が1)｜終了期: 累計を終える期｜支払期日: 0=期末払い、1=期首払い(省略不可)"],
"DB":["=DB(取得価額, 残存価額, 耐用年数, 期, [月])","取得価額: 資産の取得価額｜残存価額: 耐用年数終了時の価額｜耐用年数: 償却する期間の数｜期: 償却費を求める期(耐用年数と同じ単位)｜月: 初年度の月数(省略時 12)"],
"DDB":["=DDB(取得価額, 残存価額, 耐用年数, 期, [率])","取得価額: 資産の取得価額｜残存価額: 耐用年数終了時の価額｜耐用年数: 償却する期間の数｜期: 償却費を求める期｜率: 償却率の倍率(省略時 2=倍額定率法)"],
"DISC":["=DISC(受渡日, 満期日, 現在価格, 償還価額, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜現在価格: 額面100あたりの価格｜償還価額: 額面100あたりの償還価額｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"DOLLARDE":["=DOLLARDE(分数表記の値, 分母)","分数表記の値: 整数部と分子を小数点で区切った値(例 1.02 = 1と2/16)｜分母: 分数の分母に使う整数(例 16、32)"],
"DOLLARFR":["=DOLLARFR(小数表記の値, 分母)","小数表記の値: 変換する小数の値｜分母: 分数の分母に使う整数(例 16、32)"],
"DURATION":["=DURATION(受渡日, 満期日, 利札, 利回り, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜利札: 年間クーポン利率｜利回り: 年間利回り｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"EFFECT":["=EFFECT(名目利率, 複利計算回数)","名目利率: 名目年利率｜複利計算回数: 1年あたりの複利計算回数"],
"FV":["=FV(利率, 期間, 定期支払額, [現在価値], [支払期日])","利率: 1期あたりの利率｜期間: 支払回数の合計｜定期支払額: 毎期の支払額(出金は負の数)｜現在価値: 現在の元本(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"FVSCHEDULE":["=FVSCHEDULE(元金, 利率配列)","元金: 現在の元本｜利率配列: 各期に適用する利率の配列・範囲"],
"INTRATE":["=INTRATE(受渡日, 満期日, 投資額, 償還価額, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜投資額: 証券への投資額｜償還価額: 満期に受け取る金額｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"IPMT":["=IPMT(利率, 期, 期間, 現在価値, [将来価値], [支払期日])","利率: 1期あたりの利率｜期: 利息を求める期(1〜期間)｜期間: 支払回数の合計｜現在価値: 借入額・元本｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"IRR":["=IRR(範囲, [推定値])","範囲: キャッシュフローの範囲(正と負の値を1つ以上ずつ含む)｜推定値: 結果に近いと思われる利率(省略時 0.1)"],
"ISPMT":["=ISPMT(利率, 期, 期間, 現在価値)","利率: 1期あたりの利率｜期: 利息を求める期(最初の期が0)｜期間: 支払回数の合計｜現在価値: 借入額"],
"MDURATION":["=MDURATION(受渡日, 満期日, 利札, 利回り, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜利札: 年間クーポン利率｜利回り: 年間利回り｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"MIRR":["=MIRR(範囲, 安全利率, 危険利率)","範囲: キャッシュフローの範囲(正と負の値を含む)｜安全利率: 支払額(負のキャッシュフロー)に対する借入利率｜危険利率: 収益額(正のキャッシュフロー)の再投資利率"],
"NOMINAL":["=NOMINAL(実効利率, 複利計算回数)","実効利率: 実効年利率｜複利計算回数: 1年あたりの複利計算回数"],
"NPER":["=NPER(利率, 定期支払額, 現在価値, [将来価値], [支払期日])","利率: 1期あたりの利率｜定期支払額: 毎期の支払額(出金は負の数)｜現在価値: 借入額・元本｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"NPV":["=NPV(割引率, 値1, [値2], …)","割引率: 1期あたりの割引率｜値1: 1期目(期末)のキャッシュフロー・範囲｜値2: 以降の期のキャッシュフロー(省略可)"],
"ODDFPRICE":["=ODDFPRICE(受渡日, 満期日, 発行日, 初回利払日, 利率, 利回り, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜発行日: 証券の発行日｜初回利払日: 最初の利払日｜利率: 年間クーポン利率｜利回り: 年間利回り｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"ODDFYIELD":["=ODDFYIELD(受渡日, 満期日, 発行日, 初回利払日, 利率, 現在価格, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜発行日: 証券の発行日｜初回利払日: 最初の利払日｜利率: 年間クーポン利率｜現在価格: 額面100あたりの価格｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"ODDLPRICE":["=ODDLPRICE(受渡日, 満期日, 最終利払日, 利率, 利回り, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜最終利払日: 受渡日より前の最後の利払日｜利率: 年間クーポン利率｜利回り: 年間利回り｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"ODDLYIELD":["=ODDLYIELD(受渡日, 満期日, 最終利払日, 利率, 現在価格, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜最終利払日: 受渡日より前の最後の利払日｜利率: 年間クーポン利率｜現在価格: 額面100あたりの価格｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"PDURATION":["=PDURATION(利率, 現在価値, 将来価値)","利率: 1期あたりの利率｜現在価値: 投資の現在の価値｜将来価値: 目標とする将来の価値"],
"PMT":["=PMT(利率, 期間, 現在価値, [将来価値], [支払期日])","利率: 1期あたりの利率(年利÷12 など)｜期間: 支払回数の合計｜現在価値: 借入額・元本｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"PPMT":["=PPMT(利率, 期, 期間, 現在価値, [将来価値], [支払期日])","利率: 1期あたりの利率｜期: 元金を求める期(1〜期間)｜期間: 支払回数の合計｜現在価値: 借入額・元本｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"PRICE":["=PRICE(受渡日, 満期日, 利率, 利回り, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜利率: 年間クーポン利率｜利回り: 年間利回り｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"PRICEDISC":["=PRICEDISC(受渡日, 満期日, 割引率, 償還価額, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜割引率: 証券の割引率｜償還価額: 額面100あたりの償還価額｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"PRICEMAT":["=PRICEMAT(受渡日, 満期日, 発行日, 利率, 利回り, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜発行日: 証券の発行日｜利率: 発行日時点の利率｜利回り: 年間利回り｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"PV":["=PV(利率, 期間, 定期支払額, [将来価値], [支払期日])","利率: 1期あたりの利率｜期間: 支払回数の合計｜定期支払額: 毎期の支払額(出金は負の数)｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い"],
"RATE":["=RATE(期間, 定期支払額, 現在価値, [将来価値], [支払期日], [推定値])","期間: 支払回数の合計｜定期支払額: 毎期の支払額(出金は負の数)｜現在価値: 借入額・元本｜将来価値: 最後の支払後に残す残高(省略時 0)｜支払期日: 0=期末払い(既定)、1=期首払い｜推定値: 結果に近いと思われる利率(省略時 0.1)"],
"RECEIVED":["=RECEIVED(受渡日, 満期日, 投資額, 割引率, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜投資額: 証券への投資額｜割引率: 証券の割引率｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"RRI":["=RRI(期間, 現在価値, 将来価値)","期間: 投資の期間数｜現在価値: 投資の現在の価値｜将来価値: 投資の将来の価値"],
"SLN":["=SLN(取得価額, 残存価額, 耐用年数)","取得価額: 資産の取得価額｜残存価額: 耐用年数終了時の価額｜耐用年数: 償却する期間の数"],
"SYD":["=SYD(取得価額, 残存価額, 耐用年数, 期)","取得価額: 資産の取得価額｜残存価額: 耐用年数終了時の価額｜耐用年数: 償却する期間の数｜期: 償却費を求める期(耐用年数と同じ単位)"],
"TBILLEQ":["=TBILLEQ(受渡日, 満期日, 割引率)","受渡日: 財務省短期証券の受渡日｜満期日: 満期日(受渡日から1年以内)｜割引率: 証券の割引率"],
"TBILLPRICE":["=TBILLPRICE(受渡日, 満期日, 割引率)","受渡日: 財務省短期証券の受渡日｜満期日: 満期日(受渡日から1年以内)｜割引率: 証券の割引率"],
"TBILLYIELD":["=TBILLYIELD(受渡日, 満期日, 現在価格)","受渡日: 財務省短期証券の受渡日｜満期日: 満期日(受渡日から1年以内)｜現在価格: 額面100あたりの価格"],
"VDB":["=VDB(取得価額, 残存価額, 耐用年数, 開始期, 終了期, [率], [切り替えなし])","取得価額: 資産の取得価額｜残存価額: 耐用年数終了時の価額｜耐用年数: 償却する期間の数｜開始期: 償却費を求める期間の始まり｜終了期: 償却費を求める期間の終わり｜率: 償却率の倍率(省略時 2=倍額定率法)｜切り替えなし: FALSE=定額法の償却費の方が大きくなったら定額法に切り替える(既定)、TRUE=切り替えない"],
"XIRR":["=XIRR(範囲, 日付, [推定値])","範囲: キャッシュフローの範囲(正と負の値を1つ以上ずつ含む)｜日付: 各キャッシュフローの発生日の範囲｜推定値: 結果に近いと思われる利率(省略時 0.1)"],
"XNPV":["=XNPV(割引率, キャッシュフロー, 日付)","割引率: キャッシュフローに適用する年間割引率｜キャッシュフロー: 収支の範囲｜日付: 各キャッシュフローの発生日の範囲"],
"YIELD":["=YIELD(受渡日, 満期日, 利率, 現在価格, 償還価額, 頻度, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜利率: 年間クーポン利率｜現在価格: 額面100あたりの価格｜償還価額: 額面100あたりの償還価額｜頻度: 年間の利払回数 1=年1回、2=半年ごと、4=四半期ごと｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"YIELDDISC":["=YIELDDISC(受渡日, 満期日, 現在価格, 償還価額, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜現在価格: 額面100あたりの価格｜償還価額: 額面100あたりの償還価額｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"YIELDMAT":["=YIELDMAT(受渡日, 満期日, 発行日, 利率, 現在価格, [基準])","受渡日: 証券の受渡日｜満期日: 証券の満期日｜発行日: 証券の発行日｜利率: 発行日時点の利率｜現在価格: 額面100あたりの価格｜基準: 日数計算 0=米国30/360(既定)、1=実際/実際、2=実際/360、3=実際/365、4=欧州30/360"],
"CELL":["=CELL(検査の種類, [参照])","検査の種類: \"address\"=番地、\"col\"=列番号、\"row\"=行番号、\"contents\"=値、\"type\"=データの種類、\"width\"=列幅、\"filename\"/\"format\"/\"color\"/\"parentheses\"/\"prefix\"/\"protect\"(Excelのみ)｜参照: 調べるセル(Excelは省略時 最後に変更したセル、スプレッドシートは必須)"],
"ERROR.TYPE":["=ERROR.TYPE(エラー値)","エラー値: 調べるエラー。戻り値 1=#NULL!、2=#DIV/0!、3=#VALUE!、4=#REF!、5=#NAME?、6=#NUM!、7=#N/A、8=その他(エラーでなければ #N/A)"],
"INFO":["=INFO(検査の種類)","検査の種類: \"directory\"=カレントフォルダ、\"numfile\"=開いているシート数、\"origin\"=左上のセル番地、\"osversion\"=OSのバージョン、\"recalc\"=再計算モード、\"release\"=Excelのバージョン、\"system\"=動作環境"],
"ISBETWEEN":["=ISBETWEEN(値, 下限, 上限, [下限を含む], [上限を含む])","値: 判定する値｜下限: 範囲の下限｜上限: 範囲の上限｜下限を含む: TRUE=下限の値も範囲に含む(既定)、FALSE=含まない｜上限を含む: TRUE=上限の値も範囲に含む(既定)、FALSE=含まない"],
"ISBLANK":["=ISBLANK(値)","値: 空白かどうか調べるセル"],
"ISDATE":["=ISDATE(値)","値: 日付かどうか調べる値"],
"ISEMAIL":["=ISEMAIL(値)","値: メールアドレスの形式かどうか調べる文字列"],
"ISERR":["=ISERR(値)","値: #N/A 以外のエラーかどうか調べる値"],
"ISERROR":["=ISERROR(値)","値: エラーかどうか調べる値・数式"],
"ISEVEN":["=ISEVEN(数値)","数値: 偶数かどうか調べる数値(小数部は切り捨て)"],
"ISFORMULA":["=ISFORMULA(参照)","参照: 数式が入っているか調べるセル"],
"ISLOGICAL":["=ISLOGICAL(値)","値: 論理値(TRUE/FALSE)かどうか調べる値"],
"ISNA":["=ISNA(値)","値: #N/A エラーかどうか調べる値・数式"],
"ISNONTEXT":["=ISNONTEXT(値)","値: 文字列以外かどうか調べる値(空白セルも TRUE)"],
"ISNUMBER":["=ISNUMBER(値)","値: 数値かどうか調べる値"],
"ISODD":["=ISODD(数値)","数値: 奇数かどうか調べる数値(小数部は切り捨て)"],
"ISREF":["=ISREF(値)","値: 有効なセル参照かどうか調べる値"],
"ISTEXT":["=ISTEXT(値)","値: 文字列かどうか調べる値"],
"ISURL":["=ISURL(値)","値: URLの形式かどうか調べる文字列"],
"N":["=N(値)","値: 数値に変換する値(数値はそのまま、日付はシリアル値、TRUE=1、それ以外=0)"],
"NA":["=NA()","引数なし(#N/A エラーを返す)"],
"SHEET":["=SHEET([値])","値: シート名または参照(省略時 数式のあるシートの番号)"],
"SHEETS":["=SHEETS([参照])","参照: シート数を数える参照(省略時 ブック内の全シート数)。スプレッドシートは引数なし =SHEETS()"],
"TYPE":["=TYPE(値)","値: 調べる値。戻り値 1=数値、2=文字列、4=論理値、16=エラー値、64=配列、128=複合データ"],
"BESSELI":["=BESSELI(x, n)","x: 関数に代入する値｜n: ベッセル関数の次数(0以上の整数)"],
"BESSELJ":["=BESSELJ(x, n)","x: 関数に代入する値｜n: ベッセル関数の次数(0以上の整数)"],
"BESSELK":["=BESSELK(x, n)","x: 関数に代入する値(正の数)｜n: ベッセル関数の次数(0以上の整数)"],
"BESSELY":["=BESSELY(x, n)","x: 関数に代入する値(正の数)｜n: ベッセル関数の次数(0以上の整数)"],
"BIN2DEC":["=BIN2DEC(数値)","数値: 変換する2進数(最大10桁、先頭ビットは符号)"],
"BIN2HEX":["=BIN2HEX(数値, [桁数])","数値: 変換する2進数(最大10桁)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"BIN2OCT":["=BIN2OCT(数値, [桁数])","数値: 変換する2進数(最大10桁)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"BITAND":["=BITAND(数値1, 数値2)","数値1: 0以上の整数｜数値2: 0以上の整数"],
"BITLSHIFT":["=BITLSHIFT(数値, シフト数)","数値: 0以上の整数｜シフト数: 左にずらすビット数(負の数は右シフト)"],
"BITOR":["=BITOR(数値1, 数値2)","数値1: 0以上の整数｜数値2: 0以上の整数"],
"BITRSHIFT":["=BITRSHIFT(数値, シフト数)","数値: 0以上の整数｜シフト数: 右にずらすビット数(負の数は左シフト)"],
"BITXOR":["=BITXOR(数値1, 数値2)","数値1: 0以上の整数｜数値2: 0以上の整数"],
"COMPLEX":["=COMPLEX(実部, 虚部, [虚数単位])","実部: 複素数の実部｜虚部: 複素数の虚部｜虚数単位: \"i\"(既定)または \"j\""],
"CONVERT":["=CONVERT(数値, 変換前単位, 変換後単位)","数値: 変換する値｜変換前単位: 元の単位(例 \"m\"、\"kg\"、\"C\"、\"hr\")｜変換後単位: 変換先の単位(例 \"ft\"、\"lbm\"、\"F\"、\"mn\")。同じ種類の単位どうしで指定"],
"DEC2BIN":["=DEC2BIN(数値, [桁数])","数値: 変換する10進数の整数(-512〜511)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"DEC2HEX":["=DEC2HEX(数値, [桁数])","数値: 変換する10進数の整数｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"DEC2OCT":["=DEC2OCT(数値, [桁数])","数値: 変換する10進数の整数｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"DELTA":["=DELTA(数値1, [数値2])","数値1: 比較する数値｜数値2: 比較相手の数値(省略時 0)。等しければ1、異なれば0"],
"ERF":["=ERF(下限, [上限])","下限: 積分の下限｜上限: 積分の上限(省略時は 0〜下限 で積分)"],
"ERF.PRECISE":["=ERF.PRECISE(x)","x: 積分の上限(0〜x で積分)"],
"ERFC":["=ERFC(x)","x: 積分の下限(x〜∞ で積分)"],
"ERFC.PRECISE":["=ERFC.PRECISE(x)","x: 積分の下限(x〜∞ で積分)"],
"GESTEP":["=GESTEP(数値, [しきい値])","数値: 判定する値｜しきい値: 基準の値(省略時 0)。数値≧しきい値なら1、それ以外は0"],
"HEX2BIN":["=HEX2BIN(数値, [桁数])","数値: 変換する16進数(文字列可、例 \"1F\")｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"HEX2DEC":["=HEX2DEC(数値)","数値: 変換する16進数(最大10桁、文字列可)"],
"HEX2OCT":["=HEX2OCT(数値, [桁数])","数値: 変換する16進数(文字列可)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"IMABS":["=IMABS(複素数)","複素数: \"x+yi\" 形式の複素数(文字列または COMPLEX の結果)"],
"IMAGINARY":["=IMAGINARY(複素数)","複素数: 虚部を取り出す \"x+yi\" 形式の複素数"],
"IMARGUMENT":["=IMARGUMENT(複素数)","複素数: 偏角(ラジアン)を求める \"x+yi\" 形式の複素数"],
"IMCONJUGATE":["=IMCONJUGATE(複素数)","複素数: 共役を求める \"x+yi\" 形式の複素数"],
"IMCOS":["=IMCOS(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMCOSH":["=IMCOSH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMCOT":["=IMCOT(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMCOTH":["=IMCOTH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMCSC":["=IMCSC(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMCSCH":["=IMCSCH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMDIV":["=IMDIV(複素数1, 複素数2)","複素数1: 割られる複素数(分子)｜複素数2: 割る複素数(分母)"],
"IMEXP":["=IMEXP(複素数)","複素数: \"x+yi\" 形式の複素数(eのべき指数)"],
"IMLN":["=IMLN(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMLOG":["=IMLOG(複素数, 底)","複素数: \"x+yi\" 形式の複素数｜底: 対数の底"],
"IMLOG10":["=IMLOG10(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMLOG2":["=IMLOG2(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMPOWER":["=IMPOWER(複素数, 数値)","複素数: \"x+yi\" 形式の複素数(底)｜数値: べき指数"],
"IMPRODUCT":["=IMPRODUCT(複素数1, [複素数2], …)","複素数1: 掛け合わせる複素数・範囲｜複素数2: 追加で掛ける複素数(省略可)"],
"IMREAL":["=IMREAL(複素数)","複素数: 実部を取り出す \"x+yi\" 形式の複素数"],
"IMSEC":["=IMSEC(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMSECH":["=IMSECH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMSIN":["=IMSIN(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMSINH":["=IMSINH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMSQRT":["=IMSQRT(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMSUB":["=IMSUB(複素数1, 複素数2)","複素数1: 引かれる複素数｜複素数2: 引く複素数"],
"IMSUM":["=IMSUM(複素数1, [複素数2], …)","複素数1: 合計する複素数・範囲｜複素数2: 追加で足す複素数(省略可)"],
"IMTAN":["=IMTAN(複素数)","複素数: \"x+yi\" 形式の複素数"],
"IMTANH":["=IMTANH(複素数)","複素数: \"x+yi\" 形式の複素数"],
"OCT2BIN":["=OCT2BIN(数値, [桁数])","数値: 変換する8進数(最大10桁)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"OCT2DEC":["=OCT2DEC(数値)","数値: 変換する8進数(最大10桁)"],
"OCT2HEX":["=OCT2HEX(数値, [桁数])","数値: 変換する8進数(最大10桁)｜桁数: 結果の桁数(不足分は先頭を0で埋める)"],
"DAVERAGE":["=DAVERAGE(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DCOUNT":["=DCOUNT(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 数える列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DCOUNTA":["=DCOUNTA(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 数える列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DGET":["=DGET(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 取り出す列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲(一致が1件でないとエラー)"],
"DMAX":["=DMAX(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DMIN":["=DMIN(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DPRODUCT":["=DPRODUCT(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DSTDEV":["=DSTDEV(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DSTDEVP":["=DSTDEVP(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DSUM":["=DSUM(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 合計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DVAR":["=DVAR(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"DVARP":["=DVARP(データベース, フィールド, 条件)","データベース: 見出し行を含む表の範囲｜フィールド: 集計する列(見出し名を \"\" で囲むか、左から何列目かの番号)｜条件: 見出しとその下に条件を書いた範囲"],
"BETADIST":["=BETADIST(x, α, β, [A], [B])","x: 関数に代入する値(A〜Bの間)｜α: 分布のパラメーター｜β: 分布のパラメーター｜A: xの下限(省略時 0)｜B: xの上限(省略時 1)"],
"BETAINV":["=BETAINV(確率, α, β, [A], [B])","確率: ベータ分布の確率｜α: 分布のパラメーター｜β: 分布のパラメーター｜A: xの下限(省略時 0)｜B: xの上限(省略時 1)"],
"BINOMDIST":["=BINOMDIST(成功数, 試行回数, 成功率, 関数形式)","成功数: 成功する回数｜試行回数: 独立した試行の回数｜成功率: 1回の試行が成功する確率｜関数形式: TRUE=累積分布(成功数以下の確率)、FALSE=ちょうど成功数になる確率"],
"CEILING":["=CEILING(数値, 基準値)","数値: 切り上げる数値｜基準値: 倍数の基準(スプレッドシートは省略可、省略時 1)"],
"CHIDIST":["=CHIDIST(x, 自由度)","x: 分布を評価する値(0以上)｜自由度: 自由度"],
"CHIINV":["=CHIINV(確率, 自由度)","確率: カイ二乗分布の右側確率｜自由度: 自由度"],
"CHITEST":["=CHITEST(実測値範囲, 期待値範囲)","実測値範囲: 観測値の範囲｜期待値範囲: 期待値の範囲(実測値範囲と同じ大きさ)"],
"CONFIDENCE":["=CONFIDENCE(α, 標準偏差, 標本数)","α: 有意水準(0.05 で信頼度95%)｜標準偏差: 母集団の標準偏差｜標本数: 標本の大きさ"],
"COVAR":["=COVAR(配列1, 配列2)","配列1: 1つ目のデータ範囲｜配列2: 2つ目のデータ範囲(配列1と同じ個数)"],
"CRITBINOM":["=CRITBINOM(試行回数, 成功率, α)","試行回数: ベルヌーイ試行の回数｜成功率: 1回の試行が成功する確率｜α: 基準値(0〜1)"],
"EXPONDIST":["=EXPONDIST(x, λ, 関数形式)","x: 関数に代入する値(0以上)｜λ: パラメーター(正の数)｜関数形式: TRUE=累積分布関数、FALSE=確率密度関数"],
"FDIST":["=FDIST(x, 自由度1, 自由度2)","x: 関数に代入する値(0以上)｜自由度1: 分子の自由度｜自由度2: 分母の自由度"],
"FINV":["=FINV(確率, 自由度1, 自由度2)","確率: F分布の右側確率｜自由度1: 分子の自由度｜自由度2: 分母の自由度"],
"FLOOR":["=FLOOR(数値, 基準値)","数値: 切り捨てる数値｜基準値: 倍数の基準(スプレッドシートは省略可、省略時 1)"],
"FORECAST":["=FORECAST(x, 既知のy, 既知のx)","x: 予測したい点のxの値｜既知のy: 既知のyの値の範囲(従属変数)｜既知のx: 既知のxの値の範囲(独立変数)"],
"FTEST":["=FTEST(配列1, 配列2)","配列1: 1つ目のデータ範囲｜配列2: 2つ目のデータ範囲"],
"GAMMADIST":["=GAMMADIST(x, α, β, 関数形式)","x: 関数に代入する値(0以上)｜α: 形状パラメーター｜β: 尺度パラメーター｜関数形式: TRUE=累積分布関数、FALSE=確率密度関数"],
"GAMMAINV":["=GAMMAINV(確率, α, β)","確率: ガンマ分布の確率｜α: 形状パラメーター｜β: 尺度パラメーター"],
"HYPGEOMDIST":["=HYPGEOMDIST(標本の成功数, 標本数, 母集団の成功数, 母集団の大きさ)","標本の成功数: 標本内で成功する数｜標本数: 標本の大きさ｜母集団の成功数: 母集団内で成功する数｜母集団の大きさ: 母集団全体の数"],
"LOGINV":["=LOGINV(確率, 平均, 標準偏差)","確率: 対数正規分布の確率｜平均: ln(x) の平均｜標準偏差: ln(x) の標準偏差"],
"LOGNORMDIST":["=LOGNORMDIST(x, 平均, 標準偏差)","x: 関数に代入する値(正の数)｜平均: ln(x) の平均｜標準偏差: ln(x) の標準偏差"],
"MODE":["=MODE(数値1, [数値2], …)","数値1: 最頻値を求める数値・範囲｜数値2: 追加の数値・範囲(省略可)"],
"NEGBINOMDIST":["=NEGBINOMDIST(失敗数, 成功数, 成功率)","失敗数: 失敗する回数｜成功数: 目標とする成功回数｜成功率: 1回の試行が成功する確率"],
"NORMDIST":["=NORMDIST(x, 平均, 標準偏差, 関数形式)","x: 関数に代入する値｜平均: 分布の平均｜標準偏差: 分布の標準偏差｜関数形式: TRUE=累積分布関数、FALSE=確率密度関数"],
"NORMINV":["=NORMINV(確率, 平均, 標準偏差)","確率: 正規分布の確率(0〜1)｜平均: 分布の平均｜標準偏差: 分布の標準偏差"],
"NORMSDIST":["=NORMSDIST(z)","z: 関数に代入する値(標準正規分布の累積確率を返す)"],
"NORMSINV":["=NORMSINV(確率)","確率: 標準正規分布の確率(0〜1)"],
"PERCENTILE":["=PERCENTILE(配列, 率)","配列: データの範囲｜率: 0〜1 の百分位(例 0.9=90パーセンタイル)"],
"PERCENTRANK":["=PERCENTRANK(配列, x, [有効桁数])","配列: データの範囲｜x: 順位を調べる値｜有効桁数: 結果の有効桁数(省略時 3)"],
"POISSON":["=POISSON(イベント数, 平均, 関数形式)","イベント数: 発生する事象の数｜平均: 期待される発生数｜関数形式: TRUE=累積確率(イベント数以下)、FALSE=ちょうどイベント数になる確率"],
"QUARTILE":["=QUARTILE(配列, 戻り値)","配列: データの範囲｜戻り値: 0=最小値、1=第1四分位数、2=中央値、3=第3四分位数、4=最大値"],
"RANK":["=RANK(数値, 参照, [順序])","数値: 順位を調べる数値｜参照: 比較対象の数値の範囲｜順序: 0または省略=降順(大きい順)、0以外=昇順(小さい順)"],
"STDEV":["=STDEV(数値1, [数値2], …)","数値1: 標本の数値・範囲｜数値2: 追加の数値・範囲(省略可)"],
"STDEVP":["=STDEVP(数値1, [数値2], …)","数値1: 母集団全体の数値・範囲｜数値2: 追加の数値・範囲(省略可)"],
"TDIST":["=TDIST(x, 自由度, 尾部)","x: 分布を評価する値(0以上)｜自由度: 自由度｜尾部: 1=片側分布、2=両側分布"],
"TINV":["=TINV(確率, 自由度)","確率: t分布の両側確率｜自由度: 自由度"],
"TTEST":["=TTEST(配列1, 配列2, 尾部, 検定の種類)","配列1: 1つ目のデータ範囲｜配列2: 2つ目のデータ範囲｜尾部: 1=片側、2=両側｜検定の種類: 1=対応のある検定、2=等分散の2標本、3=非等分散の2標本"],
"VAR":["=VAR(数値1, [数値2], …)","数値1: 標本の数値・範囲｜数値2: 追加の数値・範囲(省略可)"],
"VARP":["=VARP(数値1, [数値2], …)","数値1: 母集団全体の数値・範囲｜数値2: 追加の数値・範囲(省略可)"],
"WEIBULL":["=WEIBULL(x, α, β, 関数形式)","x: 関数に代入する値(0以上)｜α: 形状パラメーター｜β: 尺度パラメーター｜関数形式: TRUE=累積分布関数、FALSE=確率密度関数"],
"ZTEST":["=ZTEST(配列, x, [σ])","配列: 検定するデータの範囲｜x: 検定する値(仮説の母平均)｜σ: 母集団の標準偏差(省略時は標本標準偏差を使用)"],
"CUBEKPIMEMBER":["=CUBEKPIMEMBER(接続, KPI名, KPIのプロパティ, [キャプション])","接続: キューブへの接続名(文字列)｜KPI名: キューブ内のKPIの名前｜KPIのプロパティ: 1=値、2=目標、3=状態、4=傾向、5=重み、6=現在の時間メンバー｜キャプション: セルに表示する代替の文字列"],
"CUBEMEMBER":["=CUBEMEMBER(接続, メンバー式, [キャプション])","接続: キューブへの接続名(文字列)｜メンバー式: メンバーや組を表す多次元式(MDX)の文字列｜キャプション: セルに表示する代替の文字列"],
"CUBEMEMBERPROPERTY":["=CUBEMEMBERPROPERTY(接続, メンバー式, プロパティ)","接続: キューブへの接続名(文字列)｜メンバー式: メンバーを表す多次元式(MDX)の文字列｜プロパティ: 取得するプロパティ名の文字列"],
"CUBERANKEDMEMBER":["=CUBERANKEDMEMBER(接続, セット式, ランク, [キャプション])","接続: キューブへの接続名(文字列)｜セット式: セットを表す式、または CUBESET の入ったセル｜ランク: 取り出す順位(1が最上位)｜キャプション: セルに表示する代替の文字列"],
"CUBESET":["=CUBESET(接続, セット式, [キャプション], [並べ替え順序], [並べ替えキー])","接続: キューブへの接続名(文字列)｜セット式: メンバーや組のセットを表す式の文字列｜キャプション: セルに表示する文字列｜並べ替え順序: 0=なし(既定)、1=昇順、2=降順、3=アルファベット昇順、4=アルファベット降順、5=自然昇順、6=自然降順｜並べ替えキー: 並べ替えの基準にする値(順序が1・2のとき指定)"],
"CUBESETCOUNT":["=CUBESETCOUNT(セット)","セット: CUBESET で定義したセット(式、または CUBESET の入ったセル)"],
"CUBEVALUE":["=CUBEVALUE(接続, [メンバー式1], [メンバー式2], …)","接続: キューブへの接続名(文字列)｜メンバー式1: 集計対象を絞り込むメンバー・組・セットの式(CUBEMEMBER などのセル参照も可)｜メンバー式2: 追加の絞り込み(省略可)"],
"ENCODEURL":["=ENCODEURL(文字列)","文字列: URLエンコードする文字列"],
"FILTERXML":["=FILTERXML(XML, XPath)","XML: 有効なXML形式の文字列｜XPath: 取り出す要素を指定するXPath式の文字列"],
"IMPORTCSV":["=IMPORTCSV(パス, [スキップ行数], [取得行数], [ロケール])","パス: CSVファイルのローカルパスまたはURL(カンマ区切り・UTF-8前提)｜スキップ行数: 先頭から読み飛ばす行数(負の数は末尾から)｜取得行数: 返す行数(負の数は末尾から)｜ロケール: 日付・数値の地域書式(省略時 OSのロケール)"],
"IMPORTDATA":["=IMPORTDATA(URL, [区切り文字], [言語/地域])","URL: CSV/TSVファイルのURL(プロトコル http/https を含む)｜区切り文字: 列を分ける文字(省略時は自動判定)｜言語/地域: データ解析に使う言語・地域コード(省略時 ドキュメントの設定)"],
"IMPORTFEED":["=IMPORTFEED(URL, [クエリ], [見出し], [アイテム数])","URL: RSS/AtomフィードのURL｜クエリ: \"items\"=記事一覧(既定)、\"feed\"=フィード情報、\"feed title\"、\"items title\"、\"items url\" など｜見出し: TRUE=見出し行を付ける、FALSE=付けない(既定)｜アイテム数: 取得する件数(新しい順)"],
"IMPORTHTML":["=IMPORTHTML(URL, クエリ, 指数, [言語/地域])","URL: 対象ページのURL｜クエリ: \"table\"=表、\"list\"=リスト｜指数: ページ内で何番目の表・リストか(1始まり)｜言語/地域: データ解析に使う言語・地域コード(省略時 ドキュメントの設定)"],
"IMPORTRANGE":["=IMPORTRANGE(スプレッドシートのURL, 範囲の文字列)","スプレッドシートのURL: 読み込み元のURLまたはID｜範囲の文字列: \"シート名!A1:C10\" の形式の範囲(初回はアクセスの許可が必要)"],
"IMPORTTEXT":["=IMPORTTEXT(パス, [区切り文字], [スキップ行数], [取得行数], [エンコード], [ロケール])","パス: テキストファイルのローカルパスまたはURL｜区切り文字: 列を分ける文字(省略時 タブ)。固定長は {1,3} のように位置の配列で指定｜スキップ行数: 先頭から読み飛ばす行数(負の数は末尾から)｜取得行数: 返す行数(負の数は末尾から)｜エンコード: 文字コード(省略時 UTF-8)｜ロケール: 日付・数値の地域書式(省略時 OSのロケール)"],
"IMPORTXML":["=IMPORTXML(URL, XPathクエリ, [言語/地域])","URL: 対象ページのURL｜XPathクエリ: 取り出す要素を指定するXPath式(例 \"//h2\")｜言語/地域: データ解析に使う言語・地域コード(省略時 ドキュメントの設定)"],
"WEBSERVICE":["=WEBSERVICE(URL)","URL: データを取得するWebサービスのURL"],
"CALL":["=CALL(登録ID, [引数1], …)","登録ID: REGISTER.ID などで得た登録ID｜引数1: プロシージャに渡す値｜※別形式 =CALL(モジュール名, プロシージャ, データ型, [引数1], …) もある。マクロシート用の関数"],
"EUROCONVERT":["=EUROCONVERT(数値, 換算前通貨, 換算後通貨, [換算方法], [換算桁数])","数値: 換算する金額｜換算前通貨: ISO通貨コード(例 \"DEM\"、\"FRF\"、\"EUR\")｜換算後通貨: ISO通貨コード｜換算方法: FALSE=通貨ごとの丸め規則を適用(既定)、TRUE=丸めずに表示｜換算桁数: ユーロ経由で換算するときの中間値の有効桁数(3以上)"],
"FIELDVALUE":["=FIELDVALUE(値, フィールド名)","値: 株式・地理などのデータ型が入ったセル｜フィールド名: 取り出すフィールド名(例 \"Price\"、\"Population\")"],
"GOOGLEFINANCE":["=GOOGLEFINANCE(銘柄, [属性], [開始日], [終了日または日数], [間隔])","銘柄: 取引所:ティッカー(例 \"NASDAQ:GOOG\"、\"TYO:7203\")｜属性: \"price\"(既定)、\"priceopen\"、\"high\"、\"low\"、\"volume\"、\"marketcap\"、\"pe\"、\"eps\" など。履歴は \"open\"/\"close\"/\"high\"/\"low\"/\"volume\"/\"all\"｜開始日: 履歴の開始日｜終了日または日数: 履歴の終了日、または開始日からの日数｜間隔: \"DAILY\"(または1)、\"WEEKLY\"(または7)"],
"GOOGLETRANSLATE":["=GOOGLETRANSLATE(文字列, [元の言語], [翻訳先の言語])","文字列: 翻訳するテキスト｜元の言語: 言語コード(例 \"en\")。\"auto\" で自動検出(既定)｜翻訳先の言語: 言語コード(例 \"ja\")。省略時はシステムの言語"],
"IMAGE":["=IMAGE(ソース, [代替テキスト], [サイズ], [高さ], [幅])","ソース: 画像のURL(https)｜代替テキスト: Excelのみ。画像の説明文｜サイズ: Excelは 0=セルに合わせる(縦横比維持、既定)、1=セル全体に引き伸ばす、2=元のサイズ、3=高さ・幅を指定｜高さ: ピクセル数｜幅: ピクセル数｜※スプレッドシートは =IMAGE(URL, [モード], [高さ], [幅])。モード 1=縦横比を維持して収める(既定)、2=引き伸ばす、3=元のサイズ、4=高さ・幅を指定"],
"PY":["=PY(Pythonコード, 戻り値の種類)","Pythonコード: 実行するPythonコード(=PY と入力するとPython入力モードになる)｜戻り値の種類: 0=Excelの値、1=Pythonオブジェクト"],
"QUERY":["=QUERY(データ, クエリ, [見出し])","データ: 対象のセル範囲｜クエリ: Google Visualization APIのクエリ言語の文字列(例 \"select A, sum(B) where C > 0 group by A\")｜見出し: データ先頭の見出し行数(省略または -1 で自動判定)"],
"REGISTER.ID":["=REGISTER.ID(モジュール名, プロシージャ, [データ型])","モジュール名: DLLまたはコードリソースの名前｜プロシージャ: 関数名または番号｜データ型: 戻り値と引数のデータ型を表す文字列(登録済みなら省略可)"],
"SPARKLINE":["=SPARKLINE(データ, [オプション])","データ: グラフにする範囲・配列｜オプション: 設定名と値の組の配列(例 {\"charttype\",\"column\";\"color\",\"red\"})。charttype は \"line\"(既定)、\"bar\"、\"column\"、\"winloss\""],
"SQL.REQUEST":["=SQL.REQUEST(接続文字列, [出力先], [ドライバープロンプト], [クエリ文字列], [列名表示])","接続文字列: データソース名・ユーザーIDなどの接続情報｜出力先: 完成した接続文字列を書き出すセル｜ドライバープロンプト: 1=常にダイアログ表示、2=情報不足のときだけ表示(既定)、3=同左(不要な項目は選択不可)、4=表示しない｜クエリ文字列: 実行するSQL文｜列名表示: TRUE=1行目に列名を返す、FALSE=返さない(既定)｜※旧バージョンのアドイン関数"],
"STOCKHISTORY":["=STOCKHISTORY(銘柄, 開始日, [終了日], [間隔], [見出し], [プロパティ1], …)","銘柄: ティッカー(例 \"MSFT\"、\"XNAS:MSFT\")または株式データ型のセル｜開始日: 取得を始める日付｜終了日: 取得を終える日付(省略時 開始日)｜間隔: 0=日次(既定)、1=週次、2=月次｜見出し: 0=なし、1=見出しを表示(既定)、2=銘柄名と見出し｜プロパティ1: 取得する列 0=日付、1=終値、2=始値、3=高値、4=安値、5=出来高(省略時 日付と終値)"],
"TO_DATE":["=TO_DATE(値)","値: 日付に変換する数値(シリアル値)"],
"TO_DOLLARS":["=TO_DOLLARS(値)","値: 通貨表記に変換する数値"],
"TO_PERCENT":["=TO_PERCENT(値)","値: パーセント表記に変換する数値(1 → 100%)"],
"TO_PURE_NUMBER":["=TO_PURE_NUMBER(値)","値: 書式なしの数値に変換する日付・通貨・パーセントなどの値"],
"TO_TEXT":["=TO_TEXT(値)","値: 文字列に変換する数値・日付など(表示形式を保った文字列になる)"],
"AI":["=AI(プロンプト, [範囲])","プロンプト: Geminiへの指示文(文字列)｜範囲: 指示の対象・参考にするセル範囲(省略可)"],
"COPILOT":["=COPILOT(プロンプト1, [コンテキスト1], [プロンプト2], [コンテキスト2], …)","プロンプト1: AIへの指示文(文字列)｜コンテキスト1: 指示の対象にするセル範囲・値｜プロンプト2: 追加の指示文(省略可)｜コンテキスト2: 追加の対象範囲(省略可)"],
"ADD":["=ADD(値1, 値2)","値1: 足される数｜値2: 足す数｜※ =A1+B1 と同じ"],
"DIVIDE":["=DIVIDE(被除数, 除数)","被除数: 割られる数｜除数: 割る数(0は不可)｜※ =A1/B1 と同じ"],
"EQ":["=EQ(値1, 値2)","値1: 比較する値｜値2: 比較相手の値｜※ =A1=B1 と同じ"],
"GT":["=GT(値1, 値2)","値1: 比較する値｜値2: 比較相手の値(値1の方が大きければ TRUE)｜※ =A1>B1 と同じ"],
"GTE":["=GTE(値1, 値2)","値1: 比較する値｜値2: 比較相手の値(値1が値2以上なら TRUE)｜※ =A1>=B1 と同じ"],
"LT":["=LT(値1, 値2)","値1: 比較する値｜値2: 比較相手の値(値1の方が小さければ TRUE)｜※ =A1<B1 と同じ"],
"LTE":["=LTE(値1, 値2)","値1: 比較する値｜値2: 比較相手の値(値1が値2以下なら TRUE)｜※ =A1<=B1 と同じ"],
"MINUS":["=MINUS(値1, 値2)","値1: 引かれる数｜値2: 引く数｜※ =A1-B1 と同じ"],
"MULTIPLY":["=MULTIPLY(値1, 値2)","値1: 掛けられる数｜値2: 掛ける数｜※ =A1*B1 と同じ"],
"NE":["=NE(値1, 値2)","値1: 比較する値｜値2: 比較相手の値(等しくなければ TRUE)｜※ =A1<>B1 と同じ"],
"POW":["=POW(底, 指数)","底: べき乗する数｜指数: 何乗するか｜※ =A1^B1 と同じ"],
"UMINUS":["=UMINUS(値)","値: 符号を反転する数値｜※ =-A1 と同じ"],
"UNARY_PERCENT":["=UNARY_PERCENT(パーセント値)","パーセント値: 100で割る数値｜※ =A1% と同じ"],
"UPLUS":["=UPLUS(値)","値: そのまま返す数値｜※ =+A1 と同じ"]
});
